from datetime import timedelta
import random
import sqlite3

import config
import database
import friends
import models
import recommender
import support


class FriendsTests(support.DatabaseCase):
    """Use isolated users and future activities with explicitly controlled overlap boundaries."""

    def setUp(self):
        """Create one local profile, three synthetic friends and one real recipient."""
        super().setUp()
        self.user = database.complete_onboarding(self.connection, 'Alex', {'career'}, 'demo',
                                                 now=support.NOW)
        self.luca = self.person('Luca', 'LUCA26', {'career'})
        self.lena = self.person('Lena', 'LENA26', {'sports'})
        self.noah = self.person('Noah', 'NOAH26', {'career'})
        self.real = self.person('Mia', 'MIAK26', {'career'}, synthetic=False)
        start = support.NOW + timedelta(days=1)
        self.save([support.record(external_id='main', start=start, end=start + timedelta(hours=2)),
                   support.record(external_id='overlap', start=start + timedelta(hours=1),
                                  end=start + timedelta(hours=3)),
                   support.record(external_id='adjacent', start=start + timedelta(hours=2),
                                  end=start + timedelta(hours=4))])
        self.event_id = self.scalar('SELECT MIN(id) FROM events')
        self.overlap_id = self.event_id + 1
        self.adjacent_id = self.event_id + 2

    def person(self, name, code, directions, synthetic=True):
        """Create a fixture profile with explicit focus and sharing enabled only for demo users."""
        user_id = database.create_user(self.connection, name, is_synthetic=synthetic,
                                       sharing_opt_in=synthetic, now=support.NOW, friend_code=code)
        database.set_user_directions(self.connection, user_id, directions)
        return user_id

    def connect(self, friend_id):
        """Add one friend through the real code-based action."""
        code = database.get_user_profile(self.connection, friend_id).friend_code
        return friends.add_friend(self.connection, self.user, code, support.NOW)

    def confirm(self, user_id, event_id=None):
        """Confirm a future occurrence using the shared interaction state machine."""
        return database.save_interaction(self.connection, user_id, event_id or self.event_id,
                                         'confirm', now=support.NOW)

    def incoming(self, sender=None, event_id=None):
        """Send a real pending invitation to the current local user from one connected friend."""
        sender, event_id = sender or self.noah, event_id or self.event_id
        if sender not in set(friends.get_friends_df(self.connection, self.user).index):
            self.connect(sender)
        previous = database.get_interaction(self.connection, sender, event_id)
        if previous is None:
            self.confirm(sender, event_id)
        return friends.send_invitations(self.connection, sender, event_id, [self.user],
                                        support.NOW)[0]

    def test_code_generation_normalization_and_symmetric_add(self):
        """Generate unique permitted codes, accept LUCA26 with spaces/case and store both links."""
        rng, codes = random.Random(config.RANDOM_SEED), set()
        for _ in range(100):
            code = friends.generate_friend_code(codes, rng)
            self.assertEqual(len(code), config.FRIEND_CODE_LENGTH)
            self.assertTrue(set(code).issubset(config.FRIEND_CODE_ALPHABET))
            self.assertNotIn(code, codes)
            codes.add(code)
        added = friends.add_friend(self.connection, self.user, '  luca26 ', support.NOW)
        self.assertEqual(added, self.luca)
        self.assertEqual(set(friends.get_friends_df(self.connection, self.user).index), {self.luca})
        self.assertEqual(set(friends.get_friends_df(self.connection, self.luca).index), {self.user})

    def test_unknown_own_duplicate_and_malformed_codes(self):
        """Reject invalid friend additions with actionable errors and no extra database writes."""
        own = database.get_user_profile(self.connection, self.user).friend_code
        for code, message in [('UNKNOWN', 'not found'), ("' OR 1=1 --", 'not found'),
                               (own, 'own friend code'), (None, 'Enter a friend code')]:
            with self.assertRaisesRegex(ValueError, message):
                friends.add_friend(self.connection, self.user, code, support.NOW)
        self.connect(self.luca)
        with self.assertRaisesRegex(ValueError, 'already friends'):
            self.connect(self.luca)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM friendships'), 2)

    def test_sharing_controls_plans_names_counts_and_features(self):
        """Hide opted-out and unrelated plans everywhere, including live recommendation features."""
        self.connect(self.luca)
        self.confirm(self.luca)
        self.confirm(self.noah)
        self.assertFalse(friends.get_sharing_opt_in(self.connection, self.user))
        self.assertEqual(friends.friends_going_counts(self.connection, self.user, [self.event_id]),
                         {self.event_id: 1})
        names = friends.get_friends_going_df(self.connection, self.user, self.event_id)
        self.assertEqual(list(names['display_name']), ['Luca'])
        plans = friends.get_friend_plans_df(self.connection, self.user, support.NOW)
        self.assertEqual(len(plans), 1)
        friends.set_sharing_opt_in(self.connection, self.luca, False)
        self.assertTrue(friends.get_friend_plans_df(self.connection, self.user, support.NOW).empty)
        names = friends.get_friends_going_df(self.connection, self.user, self.event_id)
        self.assertTrue(names.empty)
        counts = friends.friends_going_counts(self.connection, self.user, [self.event_id])
        self.assertEqual(counts, {})
        event = models.event_from_row(database.get_event_row(self.connection, self.event_id))
        profile = database.get_user_profile(self.connection, self.user)
        row = recommender.event_feature_row(event, profile, counts.get(self.event_id, 0), 3)
        self.assertEqual(row['friends_going'], 0)
        friends.set_sharing_opt_in(self.connection, self.luca, True)
        after = event.start
        self.assertTrue(friends.get_friend_plans_df(self.connection, self.user, after).empty)
        with self.assertRaises(ValueError):
            friends.set_sharing_opt_in(self.connection, self.user, 1)

    def test_send_requires_confirmed_future_event_and_valid_batch(self):
        """Validate every recipient before any insert and reject unconfirmed or closed events."""
        self.connect(self.luca)
        with self.assertRaisesRegex(ValueError, 'Confirm this event'):
            friends.send_invitations(self.connection, self.user, self.event_id, [self.luca],
                                     support.NOW)
        self.confirm(self.user)
        for recipients in ([], [self.luca, self.user], [self.luca, self.noah],
                            [True], [self.luca, 999], 'LUCA26', None):
            with self.assertRaises(ValueError):
                friends.send_invitations(self.connection, self.user, self.event_id, recipients,
                                         support.NOW)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM invitations'), 0)
        with self.connection:
            self.connection.execute("UPDATE events SET status='full' WHERE id=?", (self.event_id,))
        with self.assertRaisesRegex(ValueError, 'full or closed'):
            friends.send_invitations(self.connection, self.user, self.event_id, [self.luca],
                                     support.NOW)

    def test_simulated_focus_acceptance_and_repeated_sends(self):
        """Accept matching focus, decline a different focus and never duplicate answered invites."""
        self.connect(self.luca)
        self.connect(self.lena)
        self.confirm(self.user)
        results = friends.send_invitations(self.connection, self.user, self.event_id,
                                           [self.luca, self.lena, self.luca], support.NOW)
        self.assertEqual([row['status'] for row in results], ['accepted', 'declined'])
        self.assertTrue(all(row['is_simulated'] == 1 for row in results))
        self.assertTrue(all(row['answered_at'] == database.to_db_text(support.NOW)
                            for row in results))
        self.assertEqual(database.get_interaction(self.connection, self.luca,
                                                  self.event_id)['status'], 'confirmed')
        self.assertIsNone(database.get_interaction(self.connection, self.lena, self.event_id))
        repeated = friends.send_invitations(self.connection, self.user, self.event_id,
                                            [self.luca, self.lena], support.NOW)
        self.assertEqual(results, repeated)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM invitations'), 2)

    def test_simulation_overlap_adjacent_and_existing_same_event(self):
        """Decline strict overlap, allow touching endpoints and ignore the same confirmed event."""
        for person in (self.luca, self.noah):
            self.connect(person)
        self.confirm(self.user)
        self.confirm(self.luca, self.overlap_id)
        self.confirm(self.noah, self.adjacent_id)
        self.confirm(self.noah)
        results = friends.send_invitations(self.connection, self.user, self.event_id,
                                           [self.luca, self.noah], support.NOW)
        self.assertEqual([row['status'] for row in results], ['declined', 'accepted'])
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions WHERE user_id=?',
                                     (self.noah,)), 2)

    def test_real_recipient_stays_pending_and_cannot_be_simulated(self):
        """Never invent a real user's answer even when their focus matches."""
        self.connect(self.real)
        self.confirm(self.user)
        result = friends.send_invitations(self.connection, self.user, self.event_id, [self.real],
                                          support.NOW)[0]
        self.assertEqual(result['status'], 'pending')
        self.assertEqual(result['is_simulated'], 0)
        self.assertIsNone(result['answered_at'])
        with self.assertRaisesRegex(ValueError, 'Only synthetic'):
            friends.simulate_friend_response(self.connection, result['id'], support.NOW)

    def test_accept_confirm_and_decline_transitions(self):
        """Accept once with one confirmation; declining never creates or cancels a plan."""
        invitation = self.incoming()
        result = friends.respond_to_invitation(self.connection, invitation['id'], True, support.NOW)
        self.assertEqual(result['status'], 'accepted')
        self.assertEqual(result['is_simulated'], 0)
        self.assertEqual(database.get_interaction(self.connection, self.user,
                                                  self.event_id)['status'], 'confirmed')
        self.assertEqual(friends.respond_to_invitation(self.connection, invitation['id'], True,
                                                       support.NOW), result)
        with self.assertRaisesRegex(ValueError, 'already been answered'):
            friends.respond_to_invitation(self.connection, invitation['id'], False, support.NOW)
        second = self.incoming(self.luca)
        friends.respond_to_invitation(self.connection, second['id'], False, support.NOW)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions WHERE user_id=?',
                                     (self.user,)), 1)

    def test_accept_existing_confirmation_and_cancelled_reconfirmation(self):
        """Reuse an existing confirmation and allow a cancelled plan to be confirmed again."""
        first = self.incoming()
        self.confirm(self.user)
        friends.respond_to_invitation(self.connection, first['id'], True, support.NOW)
        database.save_interaction(self.connection, self.user, self.event_id, 'cancel',
                                  now=support.NOW)
        second = self.incoming(self.luca)
        friends.respond_to_invitation(self.connection, second['id'], True, support.NOW)
        self.assertEqual(database.get_interaction(self.connection, self.user,
                                                  self.event_id)['status'], 'confirmed')
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions WHERE user_id=?',
                                     (self.user,)), 1)

    def test_acceptance_is_atomic_when_invitation_write_fails(self):
        """Roll back the new plan if saving the invitation answer fails after confirmation."""
        invitation = self.incoming()
        with self.connection:
            self.connection.execute('''CREATE TRIGGER reject_answer BEFORE UPDATE ON invitations
                BEGIN SELECT RAISE(ABORT, 'fixture failure'); END''')
        with self.assertRaises(sqlite3.IntegrityError):
            friends.respond_to_invitation(self.connection, invitation['id'], True, support.NOW)
        self.assertIsNone(database.get_interaction(self.connection, self.user, self.event_id))
        self.assertEqual(friends.get_invitations(self.connection, self.user)['received']
                         .loc[invitation['id'], 'status'], 'pending')

    def test_only_recipient_can_answer_and_late_accept_is_rejected(self):
        """Reject unauthorized IDs, nonboolean answers and expired confirmation atomically."""
        invitation = self.incoming()
        outgoing = friends.send_invitations(self.connection, self.noah, self.event_id,
                                            [self.user], support.NOW)[0]
        database.set_setting(self.connection, 'current_user_id', str(self.real))
        with self.assertRaisesRegex(ValueError, 'addressed to you'):
            friends.respond_to_invitation(self.connection, outgoing['id'], True, support.NOW)
        database.set_setting(self.connection, 'current_user_id', str(self.user))
        for invalid in (1, 'accept', None):
            with self.assertRaises(ValueError):
                friends.respond_to_invitation(self.connection, invitation['id'], invalid,
                                               support.NOW)
        start = support.record()['start']
        with self.assertRaisesRegex(ValueError, 'already started'):
            friends.respond_to_invitation(self.connection, invitation['id'], True, start)
        self.assertIsNone(database.get_interaction(self.connection, self.user, self.event_id))
        result = friends.respond_to_invitation(self.connection, invitation['id'], False, start)
        self.assertEqual(result['status'], 'declined')

    def test_invitation_queries_and_pins_are_scoped_and_current(self):
        """Combine senders, exclude answered/expired pins and keep unrelated invitations private."""
        first, second = self.incoming(), self.incoming(self.luca)
        invitations = friends.get_invitations(self.connection, self.user)
        self.assertEqual(set(invitations['received'].index), {first['id'], second['id']})
        self.assertTrue(invitations['sent'].empty)
        self.assertTrue(friends.get_invitations(self.connection, self.real)['received'].empty)
        names = friends.pending_invitation_senders(self.connection, self.user, support.NOW)
        self.assertEqual(set(names[self.event_id].split(', ')), {'Noah', 'Luca'})
        friends.respond_to_invitation(self.connection, first['id'], False, support.NOW)
        names = friends.pending_invitation_senders(self.connection, self.user, support.NOW)
        self.assertEqual(names, {self.event_id: 'Luca'})
        self.assertEqual(friends.pending_invitation_senders(self.connection, self.user,
                                                            support.record()['start']), {})

    def test_pins_override_scores_without_changing_scores_or_filters(self):
        """Rank an invited low-score event first while keeping score semantics and OR filters."""
        plain = support.event(event_id=1, series_id=1)
        invited = support.event(event_id=2, series_id=2, direction_key='sports',
                                bundle_key='sports_ball')
        profile = models.UserProfile(self.user, 'Alex', 'ABC234', {'career'}, {1})
        scorer = recommender.Recommender()
        original = scorer.score_events([plain, invited], profile)
        pinned = scorer.score_events([plain, invited], profile, invited_by_map={2: 'Lena'})
        self.assertEqual([row.event.event_id for row in pinned], [2, 1])
        self.assertAlmostEqual(pinned[0].score, original[1].score)
        self.assertAlmostEqual(pinned[1].score, original[0].score)
        self.assertTrue(pinned[0].is_invited())
        self.assertFalse(original[1].is_invited())
        filtered = recommender.filter_suggestions(pinned, profile, {'sports_ball'})
        self.assertEqual([row.event.event_id for row in filtered], [2])
